package de.ostms.lc.email.api;import de.ostms.lc.audit.service.AuditService;import de.ostms.lc.email.service.EmailService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/lcs/{lcId}/emails")public class EmailController{private final EmailService service;private final AuditService audit;public EmailController(EmailService service,AuditService audit){this.service=service;this.audit=audit;}@GetMapping("/status")public Map<String,Object> status(){return service.status();}@GetMapping public List<EmailDeliveryView> history(@PathVariable UUID lcId){return service.history(lcId);}@PostMapping public EmailDeliveryView send(@PathVariable UUID lcId,@Valid @RequestBody EmailSendRequest request,Authentication auth){var result=service.send(lcId,request,auth.getName());boolean sent="SENT".equals(result.status());String details=result.subject()+" · "+String.join(", ",result.recipients());if(sent)audit.record(auth,"EMAIL_SENT","LETTER_OF_CREDIT",lcId,details);else audit.record(auth.getName(),"EMAIL_FAILED","LETTER_OF_CREDIT",lcId,details+" · "+result.errorMessage(),false,null);return result;}}
